import fs from "node:fs";
import path from "node:path";
import { app } from "electron";
import { z } from "zod";
import { handle } from "./index";
import { CHANNELS } from "../../shared/channels";
import type { SampleClipData, SampleClipInfo } from "../../shared/onboarding";

/**
 * Practice clips for the Learn path (spec 3.2). The pack is generated by scripts/generate-samples.mjs
 * and shipped as electron-builder extraResources (`samples/`), never inside the renderer bundle. The
 * renderer only reads it through these two channels when the Learn path starts, so cold start is unaffected.
 * Real footage can replace the pack: edit resources/samples/manifest.json.
 */

const manifestSchema = z.object({
  version: z.literal(1),
  clips: z.array(
    z.object({
      id: z.string().regex(/^[a-z0-9][a-z0-9-]*$/),
      name: z.string().min(1),
      kind: z.enum(["video", "audio"]),
      file: z.string().min(1),
      mimeType: z.string().min(1),
      width: z.number().optional(),
      height: z.number().optional(),
      durationSec: z.number().nonnegative(),
      sizeBytes: z.number().nonnegative(),
      license: z.string().min(1),
    }),
  ),
});
type ManifestClip = z.infer<typeof manifestSchema>["clips"][number];

/** Hard ceiling so a bad manifest can never make main read an arbitrarily large file into memory. */
const MAX_SAMPLE_BYTES = 64 * 1024 * 1024;

export function samplesResourceRoot(): string {
  return app.isPackaged
    ? path.join(process.resourcesPath, "samples")
    : path.join(__dirname, "../../resources/samples");
}

function readManifest(root: string): ManifestClip[] {
  try {
    const raw: unknown = JSON.parse(fs.readFileSync(path.join(root, "manifest.json"), "utf8"));
    const parsed = manifestSchema.safeParse(raw);
    if (!parsed.success) return [];
    // A manifest entry must stay inside the samples folder and exist on disk.
    return parsed.data.clips.filter((clip) => {
      const full = path.resolve(root, clip.file);
      if (!full.startsWith(path.resolve(root) + path.sep) || !fs.existsSync(full)) return false;
      // Resolve symlinks so a link inside the folder cannot point outside it.
      const realRoot = fs.realpathSync(root);
      return fs.realpathSync(full).startsWith(realRoot + path.sep);
    });
  } catch {
    return [];
  }
}

export function listSamples(root: string = samplesResourceRoot()): SampleClipInfo[] {
  return readManifest(root).map((clip) => ({
    id: clip.id,
    name: clip.name,
    kind: clip.kind,
    durationSec: clip.durationSec,
    width: clip.width,
    height: clip.height,
    sizeBytes: clip.sizeBytes,
    mimeType: clip.mimeType,
    license: clip.license,
  }));
}

export async function getSample(
  id: string,
  root: string = samplesResourceRoot(),
): Promise<SampleClipData | null> {
  const clip = readManifest(root).find((entry) => entry.id === id);
  if (!clip) return null;
  const full = path.resolve(root, clip.file);
  try {
    const stat = await fs.promises.stat(full);
    if (!stat.isFile() || stat.size > MAX_SAMPLE_BYTES) return null;
    const buffer = await fs.promises.readFile(full);
    const bytes = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength) as ArrayBuffer;
    return { id: clip.id, name: path.basename(clip.file), mimeType: clip.mimeType, bytes };
  } catch {
    return null;
  }
}

export function registerSamplesIpc(): void {
  handle(CHANNELS.samplesList, z.undefined(), (): SampleClipInfo[] => listSamples());
  handle(
    CHANNELS.samplesGet,
    z.object({ id: z.string().min(1) }),
    (args): Promise<SampleClipData | null> => getSample(args.id),
  );
}
